import {fetchTicket,type Ticket} from "./ticketApi";export {fetchTicket};export type {Ticket};export type Comment={id:number;text:string};const comments=new Map<number,Comment[]>();let sequence=1;
export async function fetchComments(id:number,signal:AbortSignal):Promise<Comment[]>{signal.throwIfAborted();return (comments.get(id)??[]).map(comment=>({...comment}));}
export async function addComment(id:number,text:string,signal:AbortSignal):Promise<void>{await fetchTicket(id,signal);signal.throwIfAborted();const rows=comments.get(id)??[];comments.set(id,[...rows,{id:sequence++,text}]);}
